import {
  AppBar,
  Container,
  MenuItem,
  Select,
  Toolbar,
  Typography,
  IconButton,
} from "@material-ui/core";
import {
  createTheme,
  makeStyles,
  ThemeProvider,
} from "@material-ui/core/styles";
import { NightsStay, WbSunny } from "@material-ui/icons";
import { useHistory } from "react-router-dom";
import { CryptoState } from "../CryptoContext";
import { useTheme } from "../ThemeContext";
import AuthModal from "./Authentication/AuthModal";
import UserSidebar from "./Authentication/UserSidebar";
import { isAdminUser } from "../utils/adminAccess";

const useStyles = makeStyles((theme) => ({
  appBar: {
    backdropFilter: "blur(15px)",
    backgroundColor: "rgba(13, 15, 18, 0.75)",
    borderBottom: "1px solid rgba(255, 255, 255, 0.05)",
    transition: "all 0.3s ease",
  },
  appBarLight: {
    backdropFilter: "blur(15px)",
    backgroundColor: "rgba(248, 249, 250, 0.8)",
    borderBottom: "1px solid rgba(0, 0, 0, 0.05)",
    transition: "all 0.3s ease",
  },
  titleContainer: {
    display: "flex",
    alignItems: "center",
    gap: 12,
    cursor: "pointer",
    flex: 1,
  },
  title: {
    fontWeight: 800,
    background: "-webkit-linear-gradient(45deg, #FFD700 30%, #FFA500 90%)",
    WebkitBackgroundClip: "text",
    WebkitTextFillColor: "transparent",
    letterSpacing: "0.5px",
  },
  titleLight: {
    fontWeight: 800,
    background: "-webkit-linear-gradient(45deg, #d4af37 30%, #b8860b 90%)",
    WebkitBackgroundClip: "text",
    WebkitTextFillColor: "transparent",
    letterSpacing: "0.5px",
  },
  logo: {
    height: 36,
    width: 36,
    borderRadius: "50%",
    objectFit: "cover",
    animation: "$logoRotate 12s linear infinite",
    boxShadow: "0 0 10px rgba(255, 215, 0, 0.3)",
  },
  navLink: {
    fontWeight: 600,
    cursor: "pointer",
    color: "#fff",
    marginRight: "24px",
    transition: "color 0.2s ease, text-shadow 0.2s ease",
    "&:hover": {
      color: "#FFD700",
      textShadow: "0 0 8px rgba(255, 215, 0, 0.4)",
    },
  },
  navLinkLight: {
    fontWeight: 600,
    cursor: "pointer",
    color: "#333",
    marginRight: "24px",
    transition: "color 0.2s ease, text-shadow 0.2s ease",
    "&:hover": {
      color: "#d4af37",
      textShadow: "0 0 8px rgba(212, 175, 55, 0.2)",
    },
  },
  themeButton: {
    marginRight: "16px",
    transition: "transform 0.3s ease",
    "&:hover": {
      transform: "rotate(30deg) scale(1.1)",
    },
  },
  selectRoot: {
    width: 90,
    height: 40,
    borderRadius: 8,
    backgroundColor: "rgba(0,0,0,0.2)",
    color: "#FFD700",
    "& .MuiOutlinedInput-notchedOutline": {
      borderColor: "rgba(255, 215, 0, 0.3)",
    },
    "&:hover .MuiOutlinedInput-notchedOutline": {
      borderColor: "rgba(255, 215, 0, 0.6)",
    },
    "&.Mui-focused .MuiOutlinedInput-notchedOutline": {
      borderColor: "#FFD700",
    },
    "& .MuiSelect-icon": {
      color: "#FFD700",
    },
  },
  selectRootLight: {
    width: 90,
    height: 40,
    borderRadius: 8,
    backgroundColor: "rgba(255,255,255,0.5)",
    color: "#d4af37",
    "& .MuiOutlinedInput-notchedOutline": {
      borderColor: "rgba(212, 175, 55, 0.3)",
    },
    "&:hover .MuiOutlinedInput-notchedOutline": {
      borderColor: "rgba(212, 175, 55, 0.6)",
    },
    "&.Mui-focused .MuiOutlinedInput-notchedOutline": {
      borderColor: "#d4af37",
    },
    "& .MuiSelect-icon": {
      color: "#d4af37",
    },
  },
  "@keyframes logoRotate": {
    from: { transform: "rotate(0deg)" },
    to: { transform: "rotate(360deg)" },
  },
}));

const darkTheme = createTheme({
  palette: {
    primary: { main: "#fff" },
    type: "dark",
  },
  typography: { fontFamily: "'Montserrat', 'Inter', sans-serif" },
});

const lightTheme = createTheme({
  palette: {
    primary: { main: "#000" },
    type: "light",
  },
  typography: { fontFamily: "'Montserrat', 'Inter', sans-serif" },
});

function Header() {
  const classes = useStyles();
  const { currency, setCurrency, user } = CryptoState();
  const isAdmin = isAdminUser(user);
  const { isDarkMode, toggleTheme } = useTheme();
  const history = useHistory();
  const theme = isDarkMode ? darkTheme : lightTheme;

  return (
    <ThemeProvider theme={theme}>
      <AppBar
        elevation={0}
        position="sticky"
        className={isDarkMode ? classes.appBar : classes.appBarLight}
      >
        <Container>
          <Toolbar disableGutters>
            <div className={classes.titleContainer} onClick={() => history.push(`/`)}>
              <img src="/crypto.jpg" alt="Crypto Logo" className={classes.logo} />
              <Typography variant="h6" className={isDarkMode ? classes.title : classes.titleLight}>
                Crypto Tracker
              </Typography>
            </div>

            <IconButton
              onClick={toggleTheme}
              className={classes.themeButton}
              style={{ color: isDarkMode ? "#FFD700" : "#d4af37" }}
              title={isDarkMode ? "Switch to Light Mode" : "Switch to Dark Mode"}
            >
              {isDarkMode ? <WbSunny /> : <NightsStay />}
            </IconButton>

            <Typography
              onClick={() => history.push(`/news`)}
              variant="body1"
              className={isDarkMode ? classes.navLink : classes.navLinkLight}
            >
              News
            </Typography>

            <Typography
              onClick={() => history.push(`/about`)}
              variant="body1"
              className={isDarkMode ? classes.navLink : classes.navLinkLight}
            >
              About
            </Typography>

            <Typography
              onClick={() => history.push(`/contact`)}
              variant="body1"
              className={isDarkMode ? classes.navLink : classes.navLinkLight}
            >
              Contact
            </Typography>

            <Typography
              onClick={() => history.push(`/ai`)}
              variant="body1"
              className={isDarkMode ? classes.navLink : classes.navLinkLight}
            >
              Rubina (ai)
            </Typography>

            {isAdmin && (
              <Typography
                onClick={() => history.push(`/traffic`)}
                variant="body1"
                className={isDarkMode ? classes.navLink : classes.navLinkLight}
              >
                Traffic
              </Typography>
            )}

            <Select
              variant="outlined"
              value={currency}
              className={isDarkMode ? classes.selectRoot : classes.selectRootLight}
              inputProps={{ style: { padding: "10px 14px", fontWeight: 600 } }}
              MenuProps={{
                PaperProps: {
                  style: {
                    backgroundColor: isDarkMode ? "#0d0f12" : "#fff",
                    color: isDarkMode ? "white" : "black",
                    border: isDarkMode ? "1px solid rgba(255, 215, 0, 0.2)" : "1px solid rgba(0,0,0,0.1)",
                  },
                },
              }}
              onChange={(e) => setCurrency(e.target.value)}
            >
              <MenuItem value={"USD"}>USD</MenuItem>
              <MenuItem value={"INR"}>INR</MenuItem>
              <MenuItem value={"EUR"}>EUR</MenuItem>
            </Select>

            <div style={{ marginLeft: 16 }}>
              {user ? <UserSidebar /> : <AuthModal />}
            </div>
          </Toolbar>
        </Container>
      </AppBar>
    </ThemeProvider>
  );
}

export default Header;
